package com.sopia.batchman.entities;

public class Flow {

	private int homevisit;
	private int totalusers;
	private int currentonline;
	private int totalcourse;
	private int totalknowledge;
	
	public Flow() {
		super();
		// TODO Auto-generated constructor stub
	}
	public int getHomevisit() {
		return homevisit;
	}
	public void setHomevisit(int homevisit) {
		this.homevisit = homevisit;
	}
	public int getTotalusers() {
		return totalusers;
	}
	public void setTotalusers(int totalusers) {
		this.totalusers = totalusers;
	}
	public int getCurrentonline() {
		return currentonline;
	}
	public void setCurrentonline(int currentonline) {
		this.currentonline = currentonline;
	}
	public int getTotalcourse() {
		return totalcourse;
	}
	public void setTotalcourse(int totalcourse) {
		this.totalcourse = totalcourse;
	}
	public int getTotalknowledge() {
		return totalknowledge;
	}
	public void setTotalknowledge(int totalknowledge) {
		this.totalknowledge = totalknowledge;
	}
	
}
